#include <vector>

using namespace std;

class Solution {
public:
    int minimumSize(vector<int>& nums, int maxOperations) {
        int low = 1, high = *max_element(nums.begin(), nums.end());

        while (low < high) {
            int mid = (low + high) / 2, ops = 0;
            for (int n : nums)
                ops += (n - 1) / mid;
            if (ops > maxOperations) low = mid + 1;
            else high = mid;
        }

        return low;
    }
};
